"use client";

import { useEffect, useMemo, useState } from "react";
import type { VehjoData } from "./lib/google-sheets";
import { release } from "./version";

type IconName = "overview" | "clients" | "farms" | "contracts" | "receive" | "pay" | "bank" | "billing" | "invoice" | "stock" | "people" | "assets" | "settings" | "search" | "bell" | "shield" | "download" | "report";
type InstallPrompt = Event & { prompt: () => Promise<void>; userChoice: Promise<{ outcome: "accepted" | "dismissed" }> };

const nav: Array<{ label: string; icon: IconName; group?: string }> = [
  { label: "Visão geral", icon: "overview", group: "Principal" }, { label: "Clientes", icon: "clients", group: "Operações" }, { label: "Fazendas", icon: "farms" }, { label: "Contratos", icon: "contracts" },
  { label: "Contas a Receber", icon: "receive", group: "Financeiro" }, { label: "Contas a Pagar", icon: "pay" }, { label: "Contas Bancárias", icon: "bank" }, { label: "Fornecedores", icon: "clients" }, { label: "Plano de Contas", icon: "billing" }, { label: "Orçamento", icon: "billing" }, { label: "Transferências", icon: "bank" }, { label: "DRE Gerencial", icon: "billing" }, { label: "Fluxo de Caixa", icon: "bank" }, { label: "Faturamento e DER", icon: "billing" }, { label: "Notas Fiscais", icon: "invoice" },
  { label: "Estoque", icon: "stock", group: "Gestão" }, { label: "Recursos Humanos", icon: "people" }, { label: "Patrimônio", icon: "assets" },
  { label: "Relatórios Operações", icon: "report", group: "Relatórios" }, { label: "Relatórios Financeiro", icon: "report" }, { label: "Relatórios Gestão", icon: "report" }, { label: "Configurações", icon: "settings" },
];

const numberValue = (value = "") => Number(value.replace(/[^\d,.-]/g, "").replace(/\./g, "").replace(",", ".")) || 0;
const brl = (value: number) => value.toLocaleString("pt-BR", { style: "currency", currency: "BRL", maximumFractionDigits: 0 });
const rows = (data: VehjoData, name: string) => (data.sheets[name] ?? []).slice(1).filter((row) => row.some(Boolean));
const isoDate = (value = "") => { const br = value.match(/^(\d{2})\/(\d{2})\/(\d{4})$/); return br ? `${br[3]}-${br[2]}-${br[1]}` : value.slice(0, 10); };
const brazilianDate = (value = "") => { const iso = value.match(/^(\d{4})-(\d{2})-(\d{2})$/); return iso ? `${iso[3]}/${iso[2]}/${iso[1]}` : value; };
const fixEncoding = (value = "") => value.replace(/Or\?amento/gi, "Orçamento").replace(/Situa\?\?o/gi, "Situação").replace(/Descri\?\?o/gi, "Descrição").replace(/Emiss\?o/gi, "Emissão").replace(/C\?digo/gi, "Código").replace(/Compet\?ncia/gi, "Competência").replace(/Gest\?o/gi, "Gestão").replace(/Relat\?rio/gi, "Relatório").replace(/Transfer\?ncias/gi, "Transferências").replace(/Ã§/g, "ç").replace(/Ã£/g, "ã").replace(/Ã¡/g, "á").replace(/Ã©/g, "é").replace(/Ãª/g, "ê").replace(/Ã³/g, "ó").replace(/Ãµ/g, "õ");
const displayValue = (header: string, value = "") => fixEncoding(/data|vencimento|emissão/i.test(header) ? brazilianDate(value) : value);
const safe = (value: unknown) => String(value ?? "").replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#039;" })[char] ?? char);

function emitPdfReport(title: string, data: VehjoData, summary: { area: number; contracts: number; receive: number; payable: number; balance: number; critical: number; clients: number; farms: number }, selectedRecords?: string[][], filterNote = "Todos os registros") {
  const source = data.sheets[title] ?? [];
  let headers = source[0] ?? [];
  let records = source.slice(1).filter((row) => row.some(Boolean));
  if (selectedRecords) records = selectedRecords;
  if (title === "Visão geral") { headers = ["Indicador", "Resultado"]; records = [["Clientes cadastrados", String(summary.clients)], ["Fazendas vinculadas", String(summary.farms)], ["Área sob gestão", `${summary.area.toLocaleString("pt-BR")} ha`], ["Contratos ativos", String(summary.contracts)], ["Contas a receber", brl(summary.receive)], ["Contas a pagar", brl(summary.payable)], ["Saldo consolidado", brl(summary.balance)], ["Itens em estoque crítico", String(summary.critical)]]; }
  if (title === "Configurações") { headers = ["Informação", "Detalhe"]; records = [["Plataforma", "VEJHO Ciclus"], ["Ambiente", "Dronefy Agro"], ["Versão", release.version], ["Data da versão", release.releasedAt], ...release.improvements.map((item) => ["Melhoria", item])]; }
  const popup = window.open("", "_blank", "width=1280,height=900");
  if (!popup) return window.alert("Permita a abertura de janelas para emitir o relatório em PDF.");
  const issuedAt = new Date().toLocaleString("pt-BR");
  const body = records.map((record, rowIndex) => `<tr><td class="number">${rowIndex + 1}</td>${headers.map((_, index) => `<td>${safe(record[index] || "—")}</td>`).join("")}</tr>`).join("");
  popup.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Relatório - ${safe(title)}</title><style>@page{size:A4 landscape;margin:13mm 10mm 15mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#17211c;margin:0}.report-header{display:flex;align-items:center;justify-content:space-between;border-bottom:3px solid #0a6642;padding:0 0 14px;margin-bottom:18px}.brand{display:flex;align-items:center;gap:14px}.brand img{width:58px;height:58px;object-fit:contain}.brand h1{margin:0;font-size:22px;color:#0a5238}.brand p,.meta p{margin:4px 0 0;color:#66736c;font-size:9px}.meta{text-align:right}.meta strong{display:block;font-size:11px}.summary{display:flex;gap:12px;margin-bottom:14px}.summary div{border:1px solid #dce6e1;border-radius:8px;padding:9px 12px;background:#f4faf6}.summary b{display:block;font-size:15px;color:#0b5e40}.summary span{font-size:8px;color:#68756e}table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:7px}th{background:#0b5139;color:#fff;padding:7px 5px;text-align:left;overflow-wrap:anywhere}td{padding:6px 5px;border:1px solid #dfe6e2;vertical-align:top;overflow-wrap:anywhere}tbody tr:nth-child(even){background:#f3f8f5}.number{width:24px;text-align:center;color:#718078}.footer{position:fixed;bottom:-9mm;left:0;right:0;border-top:1px solid #cfdad4;padding-top:5px;display:flex;justify-content:space-between;font-size:7px;color:#748078}.no-print{position:fixed;right:16px;top:16px;border:0;border-radius:8px;background:#0b5139;color:#fff;padding:10px 15px;font-weight:700;cursor:pointer}@media print{.no-print{display:none}thead{display:table-header-group}tr{break-inside:avoid}}</style></head><body><button class="no-print" onclick="window.print()">Salvar em PDF</button><header class="report-header"><div class="brand"><img src="${window.location.origin}/dronefy-logo.png" alt="Dronefy"><div><h1>Dronefy Agro</h1><p>Relatório gerencial - VEJHO Ciclus</p></div></div><div class="meta"><strong>${safe(title)}</strong><p>Emitido em ${issuedAt}</p></div></header><section class="summary"><div><b>${records.length.toLocaleString("pt-BR")}</b><span>registros apresentados</span></div><div><b>${safe(filterNote)}</b><span>filtros aplicados</span></div><div><b>${safe(release.version)}</b><span>versão da plataforma</span></div></section><table><thead><tr><th class="number">#</th>${headers.map((header) => `<th>${safe(header)}</th>`).join("")}</tr></thead><tbody>${body}</tbody></table><footer class="footer"><span>Dronefy Agro - Documento gerado pelo VEJHO Ciclus</span><span>Relatório: ${safe(title)}</span></footer></body></html>`);
  popup.document.close(); popup.focus(); popup.onload = () => setTimeout(() => popup.print(), 300);
}

export default function DashboardClient({ data }: { data: VehjoData }) {
  const [active, setActive] = useState("Visão geral");
  const [menu, setMenu] = useState(false);
  const [installPrompt, setInstallPrompt] = useState<InstallPrompt | null>(null);
  const [installed, setInstalled] = useState(false);
  const [sheetData, setSheetData] = useState(data.sheets);
  const liveData = useMemo(() => ({ ...data, sheets: sheetData }), [data, sheetData]);
  useEffect(() => { if ("serviceWorker" in navigator) navigator.serviceWorker.register("/sw.js"); const capture = (event: Event) => { event.preventDefault(); setInstallPrompt(event as InstallPrompt); }; const complete = () => { setInstalled(true); setInstallPrompt(null); }; window.addEventListener("beforeinstallprompt", capture); window.addEventListener("appinstalled", complete); setInstalled(window.matchMedia("(display-mode: standalone)").matches); return () => { window.removeEventListener("beforeinstallprompt", capture); window.removeEventListener("appinstalled", complete); }; }, []);
  const install = async () => { if (installPrompt) { await installPrompt.prompt(); const choice = await installPrompt.userChoice; if (choice.outcome === "accepted") setInstallPrompt(null); } else window.alert("Para instalar, abra o menu do navegador e escolha ‘Instalar VEJHO Ciclus’ ou ‘Criar atalho’."); };
  const summary = useMemo(() => { const contracts = rows(liveData, "Contratos"); const today = new Date().toISOString().slice(0, 10); const activeContracts = contracts.filter((row) => /^(ativo|a vencer)$/i.test((row[11] ?? "").trim()) && (!row[6] || isoDate(row[6]) >= today)); const receivableSheet = liveData.sheets["Contas a Receber"] ?? []; const payableSheet = liveData.sheets["Contas a Pagar"] ?? []; const receivableValue = (receivableSheet[0] ?? []).findIndex((header) => /^valor$/i.test(header)); const payableValue = (payableSheet[0] ?? []).findIndex((header) => /^valor$/i.test(header)); return {
    area: activeContracts.reduce((sum, row) => sum + numberValue(row[7]), 0), contracts: activeContracts.length,
    receive: rows(liveData, "Contas a Receber").reduce((sum, row) => sum + numberValue(row[receivableValue >= 0 ? receivableValue : 14]), 0), payable: rows(liveData, "Contas a Pagar").reduce((sum, row) => sum + Math.abs(numberValue(row[payableValue >= 0 ? payableValue : 14])), 0), balance: rows(liveData, "Contas Bancárias").reduce((sum, row) => sum + numberValue(row[8] || row[4]), 0),
    critical: rows(liveData, "Estoque").filter((row) => numberValue(row[6]) <= numberValue(row[7])).length, clients: new Set(activeContracts.map((row) => row[1]).filter(Boolean)).size, farms: new Set(activeContracts.map((row) => row[3]).filter(Boolean)).size,
  }; }, [liveData]);

  return <main className="app-shell">
    <aside className={menu ? "sidebar open" : "sidebar"}>
      <div className="brand"><img src="/ciclus-logo.svg" alt="Ciclus"/><span>VEJHO · GESTÃO INTEGRADA</span></div>
      <div className="workspace"><div className="workspace-avatar">DA</div><div><span>Ambiente de trabalho</span><strong>Dronefy Agro</strong></div><i>⌄</i></div>
      <nav aria-label="Navegação principal">{nav.map((item) => <div key={item.label} className="nav-entry">{item.group && <span className="nav-group">{item.group}</span>}<button className={active === item.label ? "active" : ""} onClick={() => { setActive(item.label); setMenu(false); }}><Icon name={item.icon}/><span>{item.label}</span>{active === item.label && <i/>}</button></div>)}</nav>
      <div className="version-badge"><span>{release.version}</span><small>Versão atual</small></div>
      <div className="profile"><div className="avatar">DA</div><div><strong>Dronefy Agro</strong><span>Administrador</span></div><button aria-label="Opções do perfil">•••</button></div>
    </aside>
    {menu && <button className="backdrop" aria-label="Fechar menu" onClick={() => setMenu(false)}/>} 
    <section className="content"><header><div className="header-title"><button className="menu" onClick={() => setMenu(!menu)} aria-label="Abrir menu">☰</button><div><small>VEJHO CICLUS / {active.toUpperCase()}</small><h1>{active}</h1></div></div><div className="header-actions">{!installed && <button className="install-button" onClick={install}><Icon name="download"/><span>Baixar plataforma</span></button>}<button className="header-icon" aria-label="Pesquisar"><Icon name="search"/></button><button className="header-icon alert" aria-label="Notificações"><Icon name="bell"/></button><div className="live-status"><span/>Sistema operacional</div></div></header>
      {!data.connected && <div className="connection-warning"><strong>Atualização temporariamente indisponível</strong><span>{data.error}</span></div>}
      {active === "Visão geral" ? <Dashboard data={liveData} summary={summary}/> : active.startsWith("Relatórios ") ? <ReportsHub category={active.replace("Relatórios ", "") as "Operações" | "Financeiro" | "Gestão"} data={liveData} summary={summary}/> : active === "DRE Gerencial" ? <FinancialReport type={active} data={liveData}/> : <Module title={active} data={liveData} summary={summary} onChange={setSheetData}/>} 
    </section>
  </main>;
}

function Dashboard({ data, summary }: { data: VehjoData; summary: { area: number; contracts: number; receive: number; payable: number; balance: number; critical: number; clients: number; farms: number } }) {
  const metrics = [{ label: "Área sob gestão", value: `${summary.area.toLocaleString("pt-BR")} ha`, icon: "farms" as IconName, tone: "green" }, { label: "Contratos ativos", value: String(summary.contracts), icon: "contracts" as IconName, tone: "blue" }, { label: "Clientes cadastrados", value: String(summary.clients), icon: "clients" as IconName, tone: "violet" }, { label: "Fazendas vinculadas", value: String(summary.farms), icon: "farms" as IconName, tone: "amber" }];
  const today = new Date(); const todayIso = today.toISOString().slice(0, 10); const monthKey = todayIso.slice(0, 7); const yearKey = todayIso.slice(0, 4); const inFiveDays = new Date(today.getTime() + 5 * 86400000).toISOString().slice(0, 10); const fiveDaysAgo = new Date(today.getTime() - 5 * 86400000).toISOString().slice(0, 10);
  const sheetInfo = (name: string) => { const sheet = data.sheets[name] ?? []; const headers = sheet[0] ?? []; const records = sheet.slice(1).filter((row) => row.some(Boolean)); const index = (pattern: RegExp) => headers.findIndex((header) => pattern.test(header)); return { headers, records, date: index(/data|vencimento|emiss/i), due: index(/^vencimento$|^data$/i), value: index(/valor total|^valor$|total/i), balance: index(/^saldo$/i), status: index(/status|situa/i) }; };
  const monthlyTotal = (name: string) => { const info = sheetInfo(name); return info.records.reduce((sum, row) => sum + (info.date >= 0 && isoDate(row[info.date]).slice(0, 7) === monthKey ? (name === "Contas a Pagar" ? Math.abs(numberValue(row[info.value])) : numberValue(row[info.value])) : 0), 0); };
  const financialAlert = (name: string, mode: "upcoming" | "overdue") => { const info = sheetInfo(name); const pending = info.records.filter((row) => { const due = info.due >= 0 ? isoDate(row[info.due]) : ""; const status = info.status >= 0 ? row[info.status] : ""; const pendingStatus = !/pago|recebido|quitado|cancelado/i.test(status ?? ""); return pendingStatus && !!due && (mode === "upcoming" ? due >= todayIso && due <= inFiveDays : due <= fiveDaysAgo); }); return { count: pending.length, value: pending.reduce((sum, row) => sum + Math.abs(numberValue(row[info.balance >= 0 ? info.balance : info.value])), 0) }; };
  const payableAlert = financialAlert("Contas a Pagar", "upcoming"), receiveAlert = financialAlert("Contas a Receber", "overdue");
  const expenses = monthlyTotal("Contas a Pagar"), receivables = monthlyTotal("Contas a Receber"), billed = monthlyTotal("Faturamento e DER") || receivables;
  const contractRows = rows(data, "Contratos"); const activeRows = contractRows.filter((row) => /^(ativo|a vencer)$/i.test((row[11] ?? "").trim()) && (!row[6] || isoDate(row[6]) >= todayIso));
  const mrr = activeRows.reduce((sum, row) => { const start = new Date(`${isoDate(row[5])}T12:00:00`), end = new Date(`${isoDate(row[6])}T12:00:00`); const months = Math.max(1, (end.getFullYear() - start.getFullYear()) * 12 + end.getMonth() - start.getMonth()); return sum + numberValue(row[9]) / months; }, 0); const arr = mrr * 12;
  const endedThisMonth = contractRows.filter((row) => /encerrado|cancelado/i.test(row[11] ?? "") && isoDate(row[6]).slice(0, 7) === monthKey).length; const churn = activeRows.length + endedThisMonth ? endedThisMonth / (activeRows.length + endedThisMonth) * 100 : 0; const retention = 100 - churn; const ticket = summary.clients ? mrr / summary.clients : 0; const ltv = churn > 0 ? ticket / (churn / 100) : null;
  const clientInfo = sheetInfo("Clientes"); const newClients = clientInfo.records.filter((row) => clientInfo.date >= 0 && isoDate(row[clientInfo.date]).slice(0, 7) === monthKey).length; const cac = newClients ? expenses / newClients : null;
  const receiveInfo = sheetInfo("Contas a Receber"), payInfo = sheetInfo("Contas a Pagar"); const monthlyRevenue = new Map<string, number>(), monthlyExpense = new Map<string, number>(); receiveInfo.records.forEach((row) => { if (receiveInfo.date < 0) return; const key = isoDate(row[receiveInfo.date]).slice(0, 7); if (key) monthlyRevenue.set(key, (monthlyRevenue.get(key) ?? 0) + numberValue(row[receiveInfo.value])); }); payInfo.records.forEach((row) => { if (payInfo.date < 0) return; const key = isoDate(row[payInfo.date]).slice(0, 7); if (key) monthlyExpense.set(key, (monthlyExpense.get(key) ?? 0) + Math.abs(numberValue(row[payInfo.value]))); }); const revenueSeries = [...monthlyRevenue.entries()].filter(([, value]) => value > 0).sort(([a], [b]) => a.localeCompare(b)); const cagr = revenueSeries.length > 1 ? (Math.pow(revenueSeries.at(-1)![1] / revenueSeries[0][1], 12 / Math.max(1, revenueSeries.length - 1)) - 1) * 100 : null;
  const annualRevenue = [...monthlyRevenue.entries()].filter(([key]) => key.startsWith(yearKey)).reduce((sum, [, value]) => sum + value, 0), annualExpense = [...monthlyExpense.entries()].filter(([key]) => key.startsWith(yearKey)).reduce((sum, [, value]) => sum + value, 0); const chartMonths = [...new Set([...monthlyRevenue.keys(), ...monthlyExpense.keys()])].sort().slice(-12); const chartMax = Math.max(1, ...chartMonths.flatMap((key) => [monthlyRevenue.get(key) ?? 0, monthlyExpense.get(key) ?? 0]));
  const topRevenue = [...receiveInfo.records].sort((a, b) => numberValue(b[receiveInfo.value]) - numberValue(a[receiveInfo.value])).slice(0, 5), topExpense = [...payInfo.records].sort((a, b) => Math.abs(numberValue(b[payInfo.value])) - Math.abs(numberValue(a[payInfo.value]))).slice(0, 5); const receiveName = receiveInfo.headers.findIndex((header) => /^origem$/i.test(header)), receiveDescription = receiveInfo.headers.findIndex((header) => /empenho|categoria contábil/i.test(header)); const payName = payInfo.headers.findIndex((header) => /^destino$/i.test(header)), payDescription = payInfo.headers.findIndex((header) => /empenho|categoria contábil/i.test(header));
  const budgetRows = rows(data, "Orçamento"); const budgetRevenue = budgetRows.filter((row) => /^receita$/i.test(row[0] ?? "") && String(row[2]) === yearKey).reduce((sum, row) => sum + numberValue(row[15]), 0); const operatingResult = annualRevenue - annualExpense, operatingMargin = annualRevenue ? operatingResult / annualRevenue * 100 : 0, delinquency = summary.receive ? receiveAlert.value / summary.receive * 100 : 0, cashCoverage = summary.payable ? summary.balance / summary.payable : 0, burnRate = Math.max(0, expenses - receivables), runway = burnRate > 0 ? summary.balance / burnRate : null;
  const financeMetrics = [{ label: "Resultado operacional", value: brl(operatingResult), note: "Receitas menos despesas no ano" }, { label: "Margem operacional", value: `${operatingMargin.toLocaleString("pt-BR", { maximumFractionDigits: 1 })}%`, note: "Eficiência operacional" }, { label: "Inadimplência", value: `${delinquency.toLocaleString("pt-BR", { maximumFractionDigits: 1 })}%`, note: "Recebíveis atrasados há 5 dias" }, { label: "Cobertura de caixa", value: `${cashCoverage.toLocaleString("pt-BR", { maximumFractionDigits: 2 })}x`, note: "Saldo sobre contas a pagar" }, { label: "Burn rate", value: brl(burnRate), note: "Consumo líquido mensal" }, { label: "Runway", value: runway === null ? "Caixa positivo" : `${runway.toLocaleString("pt-BR", { maximumFractionDigits: 1 })} meses`, note: "Autonomia estimada de caixa" }, { label: "Variação do orçamento", value: budgetRevenue ? brl(annualRevenue - budgetRevenue) : "Sem orçamento", note: "Receita realizada versus orçada" }, { label: "Índice de eficiência", value: annualExpense ? `${(annualRevenue / annualExpense).toLocaleString("pt-BR", { maximumFractionDigits: 2 })}x` : "—", note: "Receita gerada por real gasto" }];
  const startupMetrics = [{ label: "CAGR", value: cagr === null ? "Sem histórico" : `${cagr.toLocaleString("pt-BR", { maximumFractionDigits: 1 })}%`, note: "Crescimento anual composto" }, { label: "ARR", value: brl(arr), note: "Receita recorrente anual" }, { label: "MRR", value: brl(mrr), note: "Receita recorrente mensal" }, { label: "LTV", value: ltv === null ? "Sem churn" : brl(ltv), note: "Valor do cliente" }, { label: "CAC", value: cac === null ? "Sem novos clientes" : brl(cac), note: "Custo de aquisição" }, { label: "Churn", value: `${churn.toLocaleString("pt-BR", { maximumFractionDigits: 1 })}%`, note: "Cancelamentos no mês" }, { label: "Ticket Médio", value: brl(ticket), note: "Receita média por cliente" }, { label: "Retention", value: `${retention.toLocaleString("pt-BR", { maximumFractionDigits: 1 })}%`, note: "Retenção mensal" }];
  const expiring = rows(data, "Contratos").filter((r) => { const d = numberValue(r[10]); return d >= 0 && d <= 45; }).slice(0, 4);
  const expiredContracts = rows(data, "Contratos").filter((row) => { const end = isoDate(row[6]); return end && end < todayIso; }).sort((a, b) => isoDate(b[6]).localeCompare(isoDate(a[6])));
  const stock = rows(data, "Estoque").filter((r) => numberValue(r[6]) <= numberValue(r[7])).slice(0, 4);
  return <div className="dashboard"><section className="welcome"><div><span>PAINEL EXECUTIVO</span><h2>Olá, Dronefy Agro.</h2><p>Acompanhe os principais indicadores da sua operação em uma visão integrada.</p></div><div className="welcome-mark"><img src="/ciclus-symbol.svg" alt=""/><span><b>VEJHO Ciclus</b>Gestão inteligente</span></div></section>
    <div className="metrics">{metrics.map((metric) => <article key={metric.label}><div className={`metric-icon ${metric.tone}`}><Icon name={metric.icon}/></div><span>{metric.label}</span><h3>{metric.value}</h3><small><i/>Atualizado agora</small></article>)}</div>
    <div className="quick-kpis"><article><Icon name="receive"/><div><strong>{brl(summary.receive)}</strong><span>Contas a receber</span></div></article><article><Icon name="pay"/><div><strong>{brl(summary.payable)}</strong><span>Contas a pagar</span></div></article><article><Icon name="bank"/><div><strong>{brl(summary.balance)}</strong><span>Saldo consolidado</span></div></article><article><Icon name="stock"/><div><strong>{summary.critical}</strong><span>Itens em estoque crítico</span></div></article></div>
    <div className="section-heading"><div><span>ALERTAS</span><h2>Atenção imediata</h2></div><span className="secure-status"><Icon name="bell"/> Janela financeira de 5 dias</span></div>
    <div className="alert-cards"><article className="alert-card pay-alert"><Icon name="pay"/><div><span>Pagamentos nos próximos 5 dias</span><strong>{payableAlert.count} lançamento(s)</strong><small>{brl(payableAlert.value)} a pagar</small></div></article><article className="alert-card receive-alert"><Icon name="receive"/><div><span>Recebimentos atrasados há 5 dias</span><strong>{receiveAlert.count} lançamento(s)</strong><small>{brl(receiveAlert.value)} em atraso</small></div></article><article className="alert-card stock-alert"><Icon name="stock"/><div><span>Estoque baixo</span><strong>{summary.critical} produto(s)</strong><small>Reposição recomendada</small></div></article></div>
    <div className="section-heading"><div><span>RESULTADO MENSAL</span><h2>Desempenho do mês</h2></div><span className="secure-status">Competência atual</span></div>
    <div className="monthly-cards"><article><span>Faturamento mensal</span><strong>{brl(billed)}</strong><small>Emitido na competência</small></article><article><span>Despesas</span><strong>{brl(expenses)}</strong><small>Contas lançadas no mês</small></article><article><span>Receita</span><strong>{brl(receivables)}</strong><small>Recebíveis da competência</small></article></div>
    <div className="chart-grid executive-charts"><article className="card"><CardHead icon="receive" over="FATURAMENTO" title="Mensal e anual" action={brl(annualRevenue)}/><div className="trend-bars">{chartMonths.map((key) => <div key={key}><span>{key.slice(5)}</span><i style={{ height: `${Math.max(4, (monthlyRevenue.get(key) ?? 0) / chartMax * 100)}%` }}/></div>)}</div><small>Total do mês: {brl(monthlyRevenue.get(monthKey) ?? 0)}</small></article><article className="card"><CardHead icon="pay" over="DESPESAS" title="Mensais e anuais" action={brl(annualExpense)}/><div className="trend-bars expense-bars">{chartMonths.map((key) => <div key={key}><span>{key.slice(5)}</span><i style={{ height: `${Math.max(4, (monthlyExpense.get(key) ?? 0) / chartMax * 100)}%` }}/></div>)}</div><small>Total do mês: {brl(monthlyExpense.get(monthKey) ?? 0)}</small></article></div>
    <div className="chart-grid ranking-grid"><article className="card"><CardHead icon="receive" over="RANKING" title="Maiores receitas" action="Top 5"/><div className="ranking-list">{topRevenue.map((row, index) => <div key={`${row[0]}-${index}`}><b>{index + 1}</b><span><strong>{fixEncoding(row[receiveName] || "Receita")}</strong><small>{fixEncoding(row[receiveDescription] || "Sem descrição")}</small></span><em>{brl(numberValue(row[receiveInfo.value]))}</em></div>)}</div></article><article className="card"><CardHead icon="pay" over="RANKING" title="Maiores despesas" action="Top 5"/><div className="ranking-list expense-ranking">{topExpense.map((row, index) => <div key={`${row[0]}-${index}`}><b>{index + 1}</b><span><strong>{fixEncoding(row[payName] || "Despesa")}</strong><small>{fixEncoding(row[payDescription] || "Sem descrição")}</small></span><em>{brl(Math.abs(numberValue(row[payInfo.value])))}</em></div>)}</div></article></div>
    <div className="section-heading"><div><span>SAÚDE DO NEGÓCIO</span><h2>Métricas de crescimento</h2></div><span className="secure-status">Atualização automática</span></div>
    <div className="startup-grid">{startupMetrics.map((item) => <article key={item.label}><span>{item.label}</span><strong>{item.value}</strong><small>{item.note}</small></article>)}</div>
    <div className="section-heading"><div><span>ANÁLISE CORPORATIVA</span><h2>Eficiência e sustentabilidade financeira</h2></div><span className="secure-status">Indicadores executivos</span></div>
    <div className="startup-grid finance-health-grid">{financeMetrics.map((item) => <article key={item.label}><span>{item.label}</span><strong>{item.value}</strong><small>{item.note}</small></article>)}</div>
    <div className="chart-grid"><article className="card chart-card"><CardHead icon="bank" over="FINANCEIRO" title="Posição consolidada" action="Valores atuais"/><div className="bar-chart">{[{l:"A receber",v:summary.receive,c:"green"},{l:"A pagar",v:summary.payable,c:"red"},{l:"Saldo",v:summary.balance,c:"blue"}].map((item) => { const max=Math.max(summary.receive,summary.payable,Math.abs(summary.balance),1); return <div className="bar-row" key={item.l}><span>{item.l}</span><div><i className={item.c} style={{width:`${Math.max(4,Math.abs(item.v)/max*100)}%`}}/></div><strong>{brl(item.v)}</strong></div>})}</div></article><article className="card chart-card"><CardHead icon="contracts" over="OPERAÇÃO" title="Carteira operacional" action="Resumo"/><div className="donut-wrap"><div className="donut" style={{background:`conic-gradient(#22c55e 0 ${Math.min(100,summary.contracts/Math.max(1,rows(data,"Contratos").length)*100)}%, #e7ece9 0)`}}><span><b>{summary.contracts}</b>ativos</span></div><div className="donut-legend"><p><i className="active-dot"/>Contratos ativos <b>{summary.contracts}</b></p><p><i/>Outros contratos <b>{Math.max(0,rows(data,"Contratos").length-summary.contracts)}</b></p><p><i className="farm-dot"/>Área gerida <b>{summary.area.toLocaleString("pt-BR")} ha</b></p></div></div></article></div>
    <div className="section-heading"><div><span>ACOMPANHAMENTO</span><h2>Prioridades da operação</h2></div><span className="secure-status"><Icon name="shield"/> Ambiente protegido</span></div>
    <div className="grid-main"><article className="card"><CardHead icon="contracts" over="CONTRATOS" title="Próximos vencimentos" action="Até 45 dias"/>{expiring.length ? expiring.map((r, i) => <div className="deadline" key={r[0] || i}><div className="datebox"><b>{r[10] || "—"}</b><span>DIAS</span></div><div><small>{r[0]}</small><strong>{r[2] || r[1]}</strong><span>Vencimento: {brazilianDate(r[6]) || "Não informado"}</span></div><i>→</i></div>) : <Empty/>}</article>
      <article className="card"><CardHead icon="stock" over="ALMOXARIFADO" title="Estoque crítico" action={`${summary.critical} item(ns)`}/>{stock.length ? stock.map((r, i) => <Stock key={r[0] || i} name={r[1] || "Item"} sku={`${r[0] || ""} · ${r[3] || ""}`} qty={`${r[6] || "0"} disponíveis`}/>) : <Empty/>}</article></div>
    <article className="card expired-card"><CardHead icon="contracts" over="ACOMPANHAMENTO" title="Contratos vencidos por cliente" action={`${expiredContracts.length} contrato(s)`}/>{expiredContracts.length ? <div className="expired-list">{expiredContracts.map((row, index) => { const overdue = Math.max(1, Math.floor((today.getTime() - new Date(`${isoDate(row[6])}T12:00:00`).getTime()) / 86400000)); return <div className="expired-row" key={`${row[0]}-${index}`}><div><span>CLIENTE</span><strong>{row[2] || row[1] || "Cliente não informado"}</strong></div><div><span>CONTRATO</span><strong>{row[0] || "—"}</strong></div><div><span>FAZENDA</span><strong>{row[4] || row[3] || "—"}</strong></div><div><span>VENCIMENTO</span><strong>{brazilianDate(row[6]) || "—"}</strong></div><em>{overdue} dia(s) vencido</em></div>})}</div> : <Empty/>}</article>
  </div>;
}

function FinancialReport({ type, data }: { type: "DRE Gerencial" | "Fluxo de Caixa"; data: VehjoData }) {
  const ledger = (name: string) => { const source = data.sheets[name] ?? []; const headers = source[0] ?? []; const records = source.slice(1).filter((row) => row.some(Boolean)); const index = (...labels: string[]) => headers.findIndex((header) => labels.some((label) => header.toLocaleLowerCase("pt-BR") === label.toLocaleLowerCase("pt-BR"))); return { records, index }; };
  const receive = ledger("Contas a Receber"), pay = ledger("Contas a Pagar"); const monthly = new Map<string, { revenue: number; expense: number }>();
  const add = (key: string, field: "revenue" | "expense", value: number) => { if (!key) return; const current = monthly.get(key) ?? { revenue: 0, expense: 0 }; current[field] += value; monthly.set(key, current); };
  if (type === "DRE Gerencial") {
    receive.records.forEach((row) => add(isoDate(row[receive.index("Data", "Emissão")]).slice(0, 7), "revenue", numberValue(row[receive.index("Valor")] ?? "")));
    pay.records.forEach((row) => add(isoDate(row[pay.index("Data", "Emissão")]).slice(0, 7), "expense", Math.abs(numberValue(row[pay.index("Valor")] ?? ""))));
  } else {
    receive.records.forEach((row) => add(isoDate(row[receive.index("Data", "Data Recebimento")]).slice(0, 7), "revenue", numberValue(row[receive.index("Valor", "Recebido")] ?? "")));
    pay.records.forEach((row) => add(isoDate(row[pay.index("Data", "Data Pagamento")]).slice(0, 7), "expense", Math.abs(numberValue(row[pay.index("Valor", "Pago")] ?? ""))));
  }
  let accumulated = 0; const reportRows = [...monthly.entries()].sort(([a], [b]) => a.localeCompare(b)).map(([month, values]) => { const result = values.revenue - values.expense; accumulated += result; return { month, ...values, result, accumulated }; }); const totalRevenue = reportRows.reduce((sum, row) => sum + row.revenue, 0), totalExpense = reportRows.reduce((sum, row) => sum + row.expense, 0), totalResult = totalRevenue - totalExpense;
  return <div className="module-page"><div className="module-intro"><div className="module-title"><span className="module-icon"><Icon name={type === "DRE Gerencial" ? "billing" : "bank"}/></span><div><span>GESTÃO FINANCEIRA</span><h2>{type}</h2><p>{type === "DRE Gerencial" ? "Regime de competência: receitas menos despesas por mês" : "Regime de caixa: recebimentos menos pagamentos efetivos"}</p></div></div></div><div className="module-summary"><div><strong>{brl(totalRevenue)}</strong><span>{type === "DRE Gerencial" ? "Receita total" : "Entradas"}</span></div><div><strong>{brl(totalExpense)}</strong><span>{type === "DRE Gerencial" ? "Despesas totais" : "Saídas"}</span></div><div><strong>{brl(totalResult)}</strong><span>{type === "DRE Gerencial" ? "Resultado" : "Saldo do período"}</span></div></div><section className="card table-card"><div className="table-toolbar"><strong>Apuração mensal</strong><span>{reportRows.length} competência(s)</span></div><div className="table-scroll"><table><thead><tr><th>Competência</th><th>{type === "DRE Gerencial" ? "Receita" : "Entradas"}</th><th>{type === "DRE Gerencial" ? "Despesas" : "Saídas"}</th><th>Resultado</th><th>{type === "DRE Gerencial" ? "Margem" : "Saldo acumulado"}</th></tr></thead><tbody>{reportRows.map((row) => <tr key={row.month}><td>{row.month.split("-").reverse().join("/")}</td><td>{brl(row.revenue)}</td><td>{brl(row.expense)}</td><td>{brl(row.result)}</td><td>{type === "DRE Gerencial" ? `${(row.revenue ? row.result / row.revenue * 100 : 0).toLocaleString("pt-BR", { maximumFractionDigits: 1 })}%` : brl(row.accumulated)}</td></tr>)}</tbody></table></div></section></div>;
}

function ReportsHub({ category, data, summary }: { category: "Operações" | "Financeiro" | "Gestão"; data: VehjoData; summary: { area: number; contracts: number; receive: number; payable: number; balance: number; critical: number; clients: number; farms: number } }) {
  const [start, setStart] = useState(""); const [end, setEnd] = useState(""); const [query, setQuery] = useState("");
  const sources = category === "Operações" ? ["Clientes", "Fazendas", "Contratos"] : category === "Financeiro" ? ["Contas a Receber", "Contas a Pagar", "Faturamento e DER", "Notas Fiscais", "Transferências"] : ["Estoque", "Recursos Humanos", "Patrimônio"];
  const reportRows = sources.flatMap((sheet) => { const source = data.sheets[sheet] ?? []; const headers = source[0] ?? []; const dateIndex = headers.findIndex((header) => /data|emiss|vencimento|competência|aquisição|admissão/i.test(header)); return source.slice(1).filter((row) => row.some(Boolean)).map((row) => ({ sheet, row, date: dateIndex >= 0 ? isoDate(row[dateIndex] ?? "") : "" })); }).filter((item) => (!start || !item.date || item.date >= start) && (!end || !item.date || item.date <= end) && (!query || item.row.some((value) => fixEncoding(value).toLocaleLowerCase("pt-BR").includes(query.toLocaleLowerCase("pt-BR")))));
  const categoryMetrics = category === "Operações" ? [["Contratos ativos", summary.contracts], ["Área sob gestão", `${summary.area.toLocaleString("pt-BR")} ha`], ["Clientes", summary.clients], ["Fazendas", summary.farms]] : category === "Financeiro" ? [["A receber", brl(summary.receive)], ["A pagar", brl(summary.payable)], ["Saldo bancário", brl(summary.balance)], ["Lançamentos", reportRows.length]] : [["Estoque crítico", summary.critical], ["Itens em estoque", rows(data, "Estoque").length], ["Colaboradores", rows(data, "Recursos Humanos").length], ["Bens patrimoniais", rows(data, "Patrimônio").length]];
  return <div className="module-page report-hub"><div className="module-intro"><div className="module-title"><span className="module-icon"><Icon name="report"/></span><div><span>CENTRAL DE RELATÓRIOS</span><h2>Relatórios de {category}</h2><p>Informações consolidadas dos módulos desta categoria</p></div></div><button className="primary-action" onClick={() => window.print()}><Icon name="report"/> Salvar em PDF</button></div><div className="report-hub-filters"><label><span>Busca</span><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Pesquisar nos relatórios..."/></label><label><span>Data inicial</span><input type="date" value={start} onChange={(event) => setStart(event.target.value)}/></label><label><span>Data final</span><input type="date" value={end} onChange={(event) => setEnd(event.target.value)}/></label></div><div className="report-kpis">{categoryMetrics.map(([label, value]) => <article key={label}><span>{label}</span><strong>{value}</strong></article>)}</div><section className="card table-card"><div className="table-toolbar"><strong>Consolidado de {category}</strong><span>{reportRows.length.toLocaleString("pt-BR")} registro(s)</span></div><div className="table-scroll"><table><thead><tr><th>Módulo</th><th>Código</th><th>Descrição principal</th><th>Data</th><th>Informações</th></tr></thead><tbody>{reportRows.slice(0, 1000).map((item, index) => <tr key={`${item.sheet}-${index}`}><td>{item.sheet}</td><td>{displayValue("", item.row[0]) || "—"}</td><td>{displayValue("", item.row[1] || item.row[2]) || "—"}</td><td>{brazilianDate(item.date) || "—"}</td><td>{item.row.slice(3, 8).filter(Boolean).map(fixEncoding).join(" · ") || "—"}</td></tr>)}</tbody></table></div></section></div>;
}

function CardHead({ icon, over, title, action }: { icon: IconName; over: string; title: string; action: string }) { return <div className="card-head"><div className="card-title"><span className="card-icon"><Icon name={icon}/></span><div><span>{over}</span><h3>{title}</h3></div></div><button>{action}</button></div>; }
function Stock({ name, sku, qty }: { name: string; sku: string; qty: string }) { return <div className="stock-item"><div><Icon name="stock"/></div><p><strong>{name}</strong><span>{sku}</span></p><em>{qty}</em></div>; }
function Empty() { return <div className="empty-state"><span>✓</span><strong>Tudo em ordem</strong><p>Nenhum registro requer atenção neste momento.</p></div>; }

function Module({ title, data, summary, onChange }: { title: string; data: VehjoData; summary: { area: number; contracts: number; receive: number; payable: number; balance: number; critical: number; clients: number; farms: number }; onChange: React.Dispatch<React.SetStateAction<Record<string, string[][]>>> }) {
  const [query, setQuery] = useState(""); const [editing, setEditing] = useState<{ rowIndex?: number; values: string[] } | null>(null); const [saving, setSaving] = useState(false); const [message, setMessage] = useState(""); const source = data.sheets[title] ?? []; const headers = source[0] ?? ["Código", "Descrição", "Status"]; const records = source.slice(1).map((values, index) => ({ values, rowIndex: index + 2 })).filter((r) => r.values.some(Boolean)); const filtered = records.filter((record) => !query || record.values.some((value) => value.toLowerCase().includes(query.toLowerCase()))); const navItem = nav.find((item) => item.label === title);
  const nextCode = String(records.reduce((highest, record) => { const digits = String(record.values[0] ?? "").match(/\d+/g)?.join(""); return Math.max(highest, digits ? Number(digits) : 0); }, 0) + 1);
  const clientRows = rows(data, "Clientes"); const farmRows = rows(data, "Fazendas"); const configRows = rows(data, "Configurações");
  const configuredOptions = (header: string) => configRows.filter((row) => String(row[0] ?? "").toLocaleLowerCase("pt-BR").includes(header.toLocaleLowerCase("pt-BR"))).map((row) => row[1]).filter(Boolean);
  const contractIndex = (name: string) => headers.findIndex((header) => header.toLocaleLowerCase("pt-BR") === name.toLocaleLowerCase("pt-BR"));
  const updateField = (index: number, value: string) => setEditing((current) => { if (!current) return current; const values = [...current.values]; values[index] = value; if (title === "Contratos") { const clientCode = contractIndex("Código Cliente"), clientName = contractIndex("Cliente"), farmCode = contractIndex("Código Fazenda"), farmName = contractIndex("Fazenda"); if (index === clientCode) { values[clientName] = clientRows.find((row) => row[0] === value)?.[1] ?? ""; values[farmCode] = ""; values[farmName] = ""; } if (index === farmCode) values[farmName] = farmRows.find((row) => row[0] === value)?.[2] ?? ""; const hectares = contractIndex("Hectares"), rate = contractIndex("Valor R$/ha"), total = contractIndex("Valor Total"), end = contractIndex("Data Fim"), days = contractIndex("Dias p/ Vencer"); if (total >= 0) values[total] = (numberValue(values[hectares]) * numberValue(values[rate])).toLocaleString("pt-BR", { style: "currency", currency: "BRL" }); if (days >= 0 && values[end]) values[days] = String(Math.ceil((new Date(isoDate(values[end]) + "T12:00:00").getTime() - Date.now()) / 86400000)); } return { ...current, values }; });
  const beginEdit = (record: { values: string[]; rowIndex: number }) => { const values = headers.map((header, index) => /data|vencimento|emissão/i.test(header) ? isoDate(record.values[index] ?? "") : record.values[index] ?? ""); if (title === "Contratos") { const hectares = contractIndex("Hectares"), rate = contractIndex("Valor R$/ha"), total = contractIndex("Valor Total"), end = contractIndex("Data Fim"), days = contractIndex("Dias p/ Vencer"); values[total] = (numberValue(values[hectares]) * numberValue(values[rate])).toLocaleString("pt-BR", { style: "currency", currency: "BRL" }); if (values[end]) values[days] = String(Math.ceil((new Date(isoDate(values[end]) + "T12:00:00").getTime() - Date.now()) / 86400000)); } setEditing({ rowIndex: record.rowIndex, values }); };
  const persist = async () => { if (!editing) return; setSaving(true); setMessage(""); const action = editing.rowIndex ? "update" : "create"; try { const response = await fetch("/api/records", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action, sheet: title, rowIndex: editing.rowIndex, values: editing.values }) }); const result = await response.json() as { error?: string; code?: string }; if (!response.ok) throw new Error(result.error); const savedValues = result.code ? editing.values.map((value, index) => index === 0 ? result.code! : value) : editing.values; onChange((current) => { const next = [...(current[title] ?? [headers])]; if (editing.rowIndex) next[editing.rowIndex - 1] = savedValues; else next.push(savedValues); return { ...current, [title]: next }; }); setEditing(null); setMessage(`Cadastro ${result.code ? `nº ${result.code} ` : ""}salvo com sucesso.`); } catch (error) { setMessage(error instanceof Error ? error.message : "Não foi possível salvar."); } finally { setSaving(false); } };
  const remove = async (rowIndex: number) => { if (!window.confirm("Deseja realmente excluir este cadastro?")) return; setMessage(""); const response = await fetch("/api/records", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "delete", sheet: title, rowIndex }) }); const result = await response.json() as { error?: string }; if (!response.ok) return setMessage(result.error ?? "Não foi possível excluir."); onChange((current) => ({ ...current, [title]: (current[title] ?? []).filter((_, index) => index !== rowIndex - 1) })); setMessage("Cadastro excluído com sucesso."); };
  return <div className="module-page"><div className="module-intro"><div className="module-title"><span className="module-icon"><Icon name={navItem?.icon ?? "overview"}/></span><div><span>MÓDULO DE GESTÃO</span><h2>{title}</h2><p>{records.length.toLocaleString("pt-BR")} registro(s) disponíveis</p></div></div><button className="primary-action" onClick={() => setEditing({ values: headers.map((header, index) => index === 0 && /código/i.test(header) ? nextCode : "") })}>＋ Novo cadastro</button></div>
    {message && <div className="action-message">{message}</div>}
    <div className="module-summary"><div><strong>{records.length.toLocaleString("pt-BR")}</strong><span>Total de registros</span></div><div><strong>{filtered.length.toLocaleString("pt-BR")}</strong><span>Resultados exibidos</span></div><div><strong>Ativo</strong><span>Status do módulo</span></div></div>
    <div className="card table-card"><div className="table-toolbar"><label><Icon name="search"/><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder={`Buscar em ${title.toLowerCase()}...`}/></label><span>{filtered.length} resultado(s)</span></div><div className="table-scroll"><table><thead><tr>{headers.map((h, i) => <th key={`${h}-${i}`}>{fixEncoding(h)}</th>)}<th>Ações</th></tr></thead><tbody>{filtered.length ? filtered.map((record, index) => <tr key={record.values[0] || index}>{headers.map((header, i) => <td key={i}>{displayValue(header, record.values[i]) || "—"}</td>)}<td><div className="row-actions"><button onClick={() => beginEdit(record)}>Editar</button><button className="danger" onClick={() => remove(record.rowIndex)}>Excluir</button></div></td></tr>) : <tr><td colSpan={headers.length + 1}><Empty/></td></tr>}</tbody></table></div></div>
    {editing && <div className="modal-backdrop" role="presentation"><section className="edit-modal" role="dialog" aria-modal="true" aria-labelledby="edit-title"><div className="modal-head"><div><span>{editing.rowIndex ? "EDITAR CADASTRO" : "NOVO CADASTRO"}</span><h3 id="edit-title">{title}</h3></div><button onClick={() => setEditing(null)} aria-label="Cancelar e fechar">×</button></div><div className="form-grid">{headers.map((header, index) => { const lower = header.toLocaleLowerCase("pt-BR"); const autoCode = index === 0 && /código/i.test(header); const clientCodeField = title === "Contratos" && lower === "código cliente"; const farmCodeField = title === "Contratos" && lower === "código fazenda"; const linkedName = title === "Contratos" && (lower === "cliente" || lower === "fazenda"); const calculated = title === "Contratos" && (lower === "valor total" || lower.includes("dias p/ vencer")); const options = configuredOptions(header); const farmChoices = farmRows.filter((row) => !editing.values[contractIndex("Código Cliente")] || row[1] === editing.values[contractIndex("Código Cliente")]); return <label key={`${header}-${index}`}><span>{header}{autoCode && <small> · automático</small>}{calculated && <small> · calculado</small>}</span>{clientCodeField ? <select value={editing.values[index] ?? ""} onChange={(event) => updateField(index, event.target.value)}><option value="">Selecione o cliente</option>{clientRows.map((row) => <option key={row[0]} value={row[0]}>{row[0]} — {row[1]}</option>)}</select> : farmCodeField ? <select value={editing.values[index] ?? ""} onChange={(event) => updateField(index, event.target.value)}><option value="">Selecione a fazenda</option>{farmChoices.map((row) => <option key={row[0]} value={row[0]}>{row[0]} — {row[2]}</option>)}</select> : options.length ? <select value={editing.values[index] ?? ""} onChange={(event) => updateField(index, event.target.value)}><option value="">Selecione</option>{options.map((option) => <option key={option}>{option}</option>)}</select> : <input type={/data|vencimento|emissão/i.test(header) ? "date" : "text"} value={editing.values[index] ?? ""} readOnly={autoCode || linkedName || calculated} className={autoCode || calculated ? "auto-code" : ""} onChange={(event) => updateField(index, event.target.value)}/>}</label>; })}</div><div className="modal-actions"><button className="cancel-action" onClick={() => setEditing(null)} disabled={saving}>Cancelar</button><button className="save-action" onClick={persist} disabled={saving}>{saving ? "Salvando..." : "Salvar"}</button></div></section></div>}
  </div>;
}

function Settings({ data }: { data: VehjoData }) {
  return <div className="module-page">
    <div className="module-intro"><div className="module-title"><span className="module-icon"><Icon name="settings"/></span><div><span>ADMINISTRAÇÃO</span><h2>Configurações</h2><p>Preferências gerais e informações da plataforma</p></div></div></div>
    <div className="settings-grid">
      <section className="card release-card"><div className="release-heading"><div><span>VERSÃO ATUAL</span><h3>{release.version}</h3><p>Publicada em {release.releasedAt}</p></div><img src="/ciclus-symbol.svg" alt="Ciclus"/></div><h4>Melhorias desta versão</h4><ul>{release.improvements.map((item) => <li key={item}><span>✓</span>{item}</li>)}</ul><div className="next-release"><span>Próxima versão planejada</span><strong>VC 1.0.20</strong></div></section>
      <section className="card system-card"><span>INFORMAÇÕES DO SISTEMA</span><h3>VEJHO Ciclus</h3><dl><div><dt>Ambiente</dt><dd>Dronefy Agro</dd></div><div><dt>Situação</dt><dd className="online">Operacional</dd></div><div><dt>Módulos ativos</dt><dd>{Object.keys(data.sheets).length}</dd></div><div><dt>Atualizações</dt><dd>Progressivas</dd></div></dl></section>
    </div>
  </div>;
}

